//! The looks gallery ("Moods"): one-click desktop looks that set the bar
//! style, desktop cards / visualizers, a palette, typography and the radius
//! / opacity scale together.
//!
//! A look never ships assets: its palette is generated by Mandara's HCT
//! engine from an OKLCH seed ([`LookDef::seed`]), and applying it never
//! touches the wallpaper image. With [`LookOptions::wallpaper_colors`] the
//! palette is instead taken from the *current* wallpaper using the look's
//! scheme variant.
//!
//! Applying a look from your own setup first saves that setup as the
//! [`BEFORE_PROFILE`] look profile (exactly [`SNAPSHOT_PATHS`]), so
//! "Restore my look" — or Studio's profile undo — brings it back. Switching
//! between looks keeps that first snapshot.

use serde::{Deserialize, Serialize};

use crate::desktop_cards::{self as cards, CALENDAR, FRAMED_BARS, MIRRORED_BARS, NOW_PLAYING, WAVE};
use crate::desktop_widgets::{Anchor, ClockFace, ClockWidget, DecorShape, Decoration, Depth, DesktopWidget, MonitorWidget, Placement, WidgetKind};
use crate::{BarLayout, BarPosition, ShellConfig, ThemeMode};
use mandara_theme::{Color, SchemeVariant, ThemeSource};

/// Name of the profile holding the setup from before the first look.
pub const BEFORE_PROFILE: &str = "Before looks";

/// Every config path a look may change (and its snapshot restores).
pub const SNAPSHOT_PATHS: &[&str] = &[
    "theme",
    "bar",
    "typography",
    "style",
    "desktop",
    "visualizers",
    "looks",
    "dock.media_chip",
    "wallpaper.desktop_clock",
    "wallpaper.clock_style",
    "wallpaper.clock_x",
    "wallpaper.clock_y",
    "wallpaper.clock_scale",
    "wallpaper.show_date",
    "wallpaper.show_weather",
    "wallpaper.audio_ring",
    "plugins.enabled",
    "plugins.disabled",
];

/// `[looks]`: which look is applied (empty: your own setup).
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
#[serde(default)]
pub struct LooksState {
    pub active: String,
    /// The look's palette came from the wallpaper (not its own seed).
    pub wallpaper_colors: bool,
    /// Plugins the applied look(s) switched on that were off before: ids
    /// added to `plugins.enabled`, and ids taken out of `plugins.disabled`.
    /// The next look (or "Restore my look") switches them back off unless
    /// it needs them too; plugins you had on are never in here.
    #[serde(skip_serializing_if = "Vec::is_empty")]
    pub plugins_enabled: Vec<String>,
    #[serde(skip_serializing_if = "Vec::is_empty")]
    pub plugins_undisabled: Vec<String>,
}

/// Options picked next to the gallery.
#[derive(Copy, Clone, Debug, Default, PartialEq)]
pub struct LookOptions {
    /// Take the palette from the current wallpaper (the look's variant)
    /// instead of the look's own seed. Ignored without a wallpaper.
    pub wallpaper_colors: bool,
}

/// The audio visualizer a look turns on.
#[derive(Copy, Clone, Debug, PartialEq, Eq)]
pub enum LookVisualizer {
    None,
    Wave,
    Framed,
    Mirrored,
}

/// One look.
#[derive(Copy, Clone, Debug, PartialEq)]
pub struct LookDef {
    pub id: &'static str,
    pub name: &'static str,
    pub blurb: &'static str,
    /// OKLCH `(lightness, chroma, hue°)` seed for the HCT palette.
    pub seed: (f32, f32, f32),
    pub variant: SchemeVariant,
    pub dark: bool,
    pub layout: BarLayout,
    pub position: BarPosition,
    pub screen_frame: bool,
    /// Bar zones (start, middle, end; top → bottom on a side bar).
    pub zones: [&'static [&'static str]; 3],
    pub ui_font: &'static str,
    pub display_font: &'static str,
    pub radius_scale: f32,
    pub bar_opacity: f32,
    pub now_playing: Option<Anchor>,
    pub calendar: Option<Anchor>,
    pub visualizer: LookVisualizer,
    /// The desktop clock widget (`None`: no clock).
    pub clock: Option<(ClockFace, Anchor)>,
    /// The clock sits behind the wallpaper's subject (else in front).
    pub depth: bool,
    /// A system monitor column at this anchor.
    pub monitor: Option<Anchor>,
    /// A vertical text decoration (Arabic / katakana) on the end edge.
    pub decoration: Option<&'static str>,
    pub dock_media_chip: bool,
}

