/// The look with `id`.
pub fn find(id: &str) -> Option<&'static LookDef> {
    LOOKS.iter().find(|l| l.id == id)
}

/// The dock plugin's id (a look with a dock media chip switches it on).
const DOCK_ID: &str = crate::dock::DOCK_PLUGIN_ID;
/// The hairline's mini stats plugin (shipped off: a look switches it on).
pub const MINI_STATS_ID: &str = "mini-stats";

impl LookDef {
    pub fn seed_color(&self) -> Color {
        Color::oklch(self.seed.0, self.seed.1, self.seed.2)
    }

    /// The palette source this look uses with `opts` on `cfg`.
    pub fn theme_source(&self, cfg: &ShellConfig, opts: LookOptions) -> ThemeSource {
        match (&cfg.wallpaper.path, opts.wallpaper_colors) {
            (Some(path), true) => ThemeSource::Wallpaper { path: path.clone(), variant: self.variant, seed: 0 },
            _ => ThemeSource::Seed { color: self.seed_color(), variant: self.variant },
        }
    }

    /// `cfg` with this look applied (the wallpaper image is never changed).
    pub fn apply(&self, cfg: &ShellConfig, opts: LookOptions) -> ShellConfig {
        let mut c = cfg.clone();
        c.theme.source = self.theme_source(cfg, opts);
        c.theme.mode = if self.dark { ThemeMode::Dark } else { ThemeMode::Light };
        let bar = &mut c.bar;
        bar.layout = self.layout;
        bar.position = self.position;
        bar.screen_frame = self.screen_frame;
        bar.opacity = self.bar_opacity;
        let [start, middle, end] = self.zones;
        bar.left = start.iter().map(|s| s.to_string()).collect();
        bar.center = middle.iter().map(|s| s.to_string()).collect();
        bar.right = end.iter().map(|s| s.to_string()).collect();
        c.typography.ui_font = self.ui_font.into();
        c.typography.display_font = self.display_font.into();
        c.style.radius_scale = self.radius_scale;
        c.desktop.widgets.items = self.widgets();
        c.desktop.widgets.migrated = true;
        crate::desktop_widgets::sync_depth_clock(&mut c);
        c.dock.media_chip = self.dock_media_chip;
        let wants = self.plugins();
        // What the previous look switched on and this one doesn't need goes
        // back off; what both need stays on (and stays the looks' doing).
        let prev = std::mem::take(&mut c.looks);
        undo_plugins(&mut c, &prev, &wants);
        let mut state = LooksState { active: self.id.to_string(), wallpaper_colors: matches!(c.theme.source, ThemeSource::Wallpaper { .. }), ..LooksState::default() };
        for id in wants {
            let was_disabled = c.plugins.disabled.iter().any(|d| d == id);
            c.plugins.disabled.retain(|d| d != id);
            if was_disabled || prev.plugins_undisabled.iter().any(|p| p == id) {
                state.plugins_undisabled.push(id.to_string());
            }
            let listed = c.plugins.enabled.iter().any(|e| e == id);
            if !listed {
                c.plugins.enabled.push(id.to_string());
            }
            if !listed || prev.plugins_enabled.iter().any(|p| p == id) {
                state.plugins_enabled.push(id.to_string());
            }
        }
        c.looks = state;
        c
    }

    /// The plugins this look needs on.
    pub fn plugins(&self) -> Vec<&'static str> {
        let mut wants: Vec<&'static str> = Vec::new();
        if self.dock_media_chip {
            wants.push(DOCK_ID);
        }
        if self.zones.iter().any(|z| z.contains(&MINI_STATS_ID)) {
            wants.push(MINI_STATS_ID);
        }
        wants
    }
}

/// Reverts the plugin switches recorded in `looks` except for `keep`: ids
/// a look added to `plugins.enabled` leave it again, ids it took out of
/// `plugins.disabled` go back in. A switch you changed since (the plugin
/// no longer listed, or disabled again) is left as you set it.
fn undo_plugins(c: &mut ShellConfig, looks: &LooksState, keep: &[&str]) {
    let kept = |id: &String| keep.iter().any(|k| k == id);
    for id in looks.plugins_enabled.iter().filter(|id| !kept(id)) {
        c.plugins.enabled.retain(|e| e != id);
    }
    for id in looks.plugins_undisabled.iter().filter(|id| !kept(id)) {
        if !c.plugins.disabled.iter().any(|d| d == id) && !c.plugins.enabled.iter().any(|e| e == id) {
            c.plugins.disabled.push(id.clone());
        }
    }
}

impl LookDef {
    /// The look's desktop widgets, in paint order.
    pub fn widgets(&self) -> Vec<DesktopWidget> {
        let mut list = crate::desktop_widgets::DesktopWidgetsConfig::default();
        let place = |anchor: Anchor, x: f32, y: f32| Placement { anchor, x, y, ..Placement::default() };
        if let Some((face, anchor)) = self.clock {
            let (fx, fy) = anchor.fraction();
            let inward = |f: f32, d: f32| if f < 0.25 { d } else if f > 0.75 { -d } else { 0.0 };
            let mut p = place(anchor, inward(fx, LOOK_MARGIN.0), inward(fy, LOOK_MARGIN.1));
            p.depth = if self.depth { Depth::Behind } else { Depth::Front };
            if self.depth {
                p.scale = DEPTH_CLOCK_SCALE;
            }
            list.add(DesktopWidget { place: p, kind: WidgetKind::Clock(ClockWidget { face, ..ClockWidget::default() }), ..DesktopWidget::default() });
        }
        if let Some(anchor) = self.monitor {
            let mut p = place(anchor, LOOK_MARGIN.0, 0.0);
            p.depth = Depth::Front;
            list.add(DesktopWidget { place: p, kind: WidgetKind::Monitor(MonitorWidget::default()), ..DesktopWidget::default() });
        }
        if let Some(text) = self.decoration {
            let mut p = place(Anchor::Right, -LOOK_MARGIN.0, 0.0);
            p.depth = Depth::Behind;
            p.opacity = DECORATION_OPACITY;
            // Vertical text: katakana stands one character under another;
            // Arabic keeps its joined letters, its line turned with the
            // baseline toward the screen's middle.
            let d = Decoration { shape: DecorShape::Text, text: text.into(), vertical: true, size: DECORATION_SIZE_PX, ..Decoration::default() };
            list.add(DesktopWidget { place: p, kind: WidgetKind::Decoration(d), ..DesktopWidget::default() });
        }
        let mut add = |card: &str, anchor: Anchor| {
            list.add(cards::new_card(card, anchor));
        };
        if let Some(a) = self.now_playing {
            add(NOW_PLAYING, a);
        }
        if let Some(a) = self.calendar {
            add(CALENDAR, a);
        }
        match self.visualizer {
            LookVisualizer::None => {}
            LookVisualizer::Wave => add(WAVE, Anchor::Bottom),
            LookVisualizer::Framed => add(FRAMED_BARS, Anchor::BottomLeft),
            LookVisualizer::Mirrored => add(MIRRORED_BARS, Anchor::Bottom),
        }
        list.items
    }
}

/// Inset of a look's corner / edge widgets (fractions of the display).
const LOOK_MARGIN: (f32, f32) = (0.04, 0.07);
/// A clock behind the subject is drawn large.
const DEPTH_CLOCK_SCALE: f32 = 1.8;
/// Vertical decoration text: size (reference px) and opacity.
const DECORATION_SIZE_PX: f32 = 64.0;
const DECORATION_OPACITY: f32 = 0.55;

/// Snapshot of `cfg` to restore later — `None` when a look is already
/// active (the snapshot of your own setup is kept, not replaced by a look).
pub fn before_snapshot(cfg: &ShellConfig, saved: &str) -> Option<crate::profiles::Profile> {
    if !cfg.looks.active.is_empty() {
        return None;
    }
    crate::profiles::snapshot_paths(cfg, BEFORE_PROFILE, "Your setup before the first look", SNAPSHOT_PATHS, saved).ok()
}

/// `cfg` restored from `before` (and no look active). The snapshot brings
/// the plugin lists back exactly; plugins you switched on yourself while a
/// look was applied stay on.
pub fn restore(cfg: &ShellConfig, before: &crate::profiles::Profile) -> anyhow::Result<ShellConfig> {
    let mut c = crate::profiles::apply(cfg, before)?;
    for id in &cfg.plugins.enabled {
        let looks_did = cfg.looks.plugins_enabled.contains(id);
        if !looks_did && !c.plugins.enabled.contains(id) {
            c.plugins.disabled.retain(|d| d != id);
            c.plugins.enabled.push(id.clone());
        }
    }
    c.looks = LooksState::default();
    Ok(c)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn six_original_looks_with_unique_ids() {
        let mut ids: Vec<&str> = LOOKS.iter().map(|l| l.id).collect();
        ids.sort();
        ids.dedup();
        assert_eq!(ids.len(), 6);
        for l in &LOOKS {
            assert!(find(l.id).is_some());
            let c = l.seed_color();
            assert!(c.lightness() > 0.3 && c.lightness() < 0.9, "{} seed is usable", l.id);
        }
    }

    #[test]
    fn applying_never_touches_the_wallpaper_image() {
        let mut cfg = ShellConfig::default();
        cfg.wallpaper.path = Some("/tmp/w.png".into());
        for l in &LOOKS {
            let after = l.apply(&cfg, LookOptions::default());
            assert_eq!(after.wallpaper.path, cfg.wallpaper.path);
            assert_eq!(after.looks.active, l.id);
            assert!(matches!(after.theme.source, ThemeSource::Seed { .. }));
            let wp = l.apply(&cfg, LookOptions { wallpaper_colors: true });
            assert!(matches!(wp.theme.source, ThemeSource::Wallpaper { .. }));
            assert!(wp.looks.wallpaper_colors);
        }
        // Without a wallpaper the look's own seed is used.
        let none = LOOKS[0].apply(&ShellConfig::default(), LookOptions { wallpaper_colors: true });
        assert!(matches!(none.theme.source, ThemeSource::Seed { .. }));
    }

    #[test]
    fn apply_then_restore_round_trips() {
        let mut mine = ShellConfig::default();
        mine.bar.height = 33.0;
        mine.typography.ui_font = "Cairo".into();
        mine.plugins.settings.insert("weather".into(), toml::Table::new());
        let before = before_snapshot(&mine, "2026-10-28 12:00").expect("own setup is snapshotted");
        let night = find("night-frame").unwrap().apply(&mine, LookOptions::default());
        assert_eq!(night.bar.position, BarPosition::Left);
        assert!(night.bar.screen_frame);
        let on: Vec<&str> = cards::enabled_cards(&night.desktop.widgets).map(|(_, c)| c.card.as_str()).collect();
        assert_eq!(on, [CALENDAR, MIRRORED_BARS]);
        // A second look keeps the first snapshot.
        assert!(before_snapshot(&night, "later").is_none());
        let wave = find("anfushi-wave").unwrap().apply(&night, LookOptions::default());
        assert_eq!(wave.bar.layout, BarLayout::Micro);
        let on: Vec<&str> = cards::enabled_cards(&wave.desktop.widgets).map(|(_, c)| c.card.as_str()).collect();
        assert_eq!(on, [WAVE]);
        let back = restore(&wave, &before).unwrap();
        assert_eq!(back, mine, "restoring brings the exact setup back");
        assert!(back.looks.active.is_empty());
    }

    #[test]
    fn looks_switch_on_the_plugins_they_need() {
        let mut cfg = ShellConfig::default();
        cfg.plugins.disabled.push(DOCK_ID.into());
        let forest = find("qaitbay-forest").unwrap().apply(&cfg, LookOptions::default());
        assert!(forest.dock.media_chip);
        assert!(!forest.plugins.disabled.iter().any(|d| d == DOCK_ID));
        let ink = find("pharos-ink").unwrap().apply(&cfg, LookOptions::default());
        assert!(ink.plugins.enabled.iter().any(|e| e == MINI_STATS_ID));
    }

    fn on(c: &ShellConfig, id: &str) -> bool {
        c.plugins.enabled.iter().any(|e| e == id) && !c.plugins.disabled.iter().any(|d| d == id)
    }

    #[test]
    fn the_next_look_switches_off_the_plugins_the_last_one_switched_on() {
        let mine = ShellConfig::default();
        let forest = find("qaitbay-forest").unwrap();
        let ink = find("pharos-ink").unwrap();
        let crimson = find("montaza-crimson").unwrap();
        assert_eq!(forest.plugins(), [DOCK_ID]);
        assert_eq!(ink.plugins(), [MINI_STATS_ID]);
        assert!(crimson.plugins().is_empty());
        // A → B: the dock A switched on goes off; B's mini stats come on.
        let a = forest.apply(&mine, LookOptions::default());
        assert!(on(&a, DOCK_ID) && a.looks.plugins_enabled == [DOCK_ID]);
        let b = ink.apply(&a, LookOptions::default());
        assert!(!b.plugins.enabled.iter().any(|e| e == DOCK_ID), "{:?}", b.plugins);
        assert!(on(&b, MINI_STATS_ID) && b.looks.plugins_enabled == [MINI_STATS_ID]);
        // B → C (needs none): nothing a look switched on is left.
        let c = crimson.apply(&b, LookOptions::default());
        assert_eq!(c.plugins, mine.plugins);
        assert!(c.looks.plugins_enabled.is_empty() && c.looks.plugins_undisabled.is_empty());
        // A plugin both looks need stays on, still recorded as the looks'.
        let again = forest.apply(&forest.apply(&mine, LookOptions::default()), LookOptions::default());
        assert!(on(&again, DOCK_ID) && again.looks.plugins_enabled == [DOCK_ID]);
        assert_eq!(crimson.apply(&again, LookOptions::default()).plugins, mine.plugins);
        // A plugin you had switched off that a look needed goes back off.
        let mut off = mine.clone();
        off.plugins.disabled.push(DOCK_ID.into());
        let a = forest.apply(&off, LookOptions::default());
        assert!(on(&a, DOCK_ID) && a.looks.plugins_undisabled == [DOCK_ID]);
        assert_eq!(crimson.apply(&a, LookOptions::default()).plugins, off.plugins);
        // The record survives the config file.
        let text = toml::to_string(&a).unwrap();
        let back: ShellConfig = toml::from_str(&text).unwrap();
        assert_eq!(back.looks, a.looks);
    }

    #[test]
    fn plugins_you_switched_on_are_never_switched_off_by_a_look() {
        let mut mine = ShellConfig::default();
        mine.plugins.enabled = vec![DOCK_ID.into(), MINI_STATS_ID.into(), "weather".into()];
        let forest = find("qaitbay-forest").unwrap();
        let ink = find("pharos-ink").unwrap();
        let crimson = find("montaza-crimson").unwrap();
        let mut c = mine.clone();
        for look in [forest, ink, crimson, forest, crimson] {
            c = look.apply(&c, LookOptions::default());
            for id in [DOCK_ID, MINI_STATS_ID, "weather"] {
                assert!(on(&c, id), "{} turned your {id} off", look.id);
            }
            assert!(c.looks.plugins_enabled.is_empty(), "{}: nothing was the look's doing", look.id);
        }
        assert_eq!(c.plugins, mine.plugins);
    }

    #[test]
    fn looks_then_restore_equals_the_original_config() {
        let mut mine = ShellConfig::default();
        mine.plugins.enabled.push("weather".into());
        mine.plugins.disabled.push(DOCK_ID.into());
        mine.bar.height = 31.0;
        let before = before_snapshot(&mine, "2026-10-28 12:00").expect("own setup is snapshotted");
        let a = find("qaitbay-forest").unwrap().apply(&mine, LookOptions::default());
        let b = find("pharos-ink").unwrap().apply(&a, LookOptions::default());
        assert!(on(&b, MINI_STATS_ID));
        let back = restore(&b, &before).unwrap();
        assert_eq!(back, mine, "A → B → restore is exact");
        // A plugin you switched on while a look was applied stays on.
        let mut b2 = b.clone();
        b2.plugins.enabled.push("prayer-times".into());
        let back = restore(&b2, &before).unwrap();
        assert!(on(&back, "prayer-times") && !on(&back, MINI_STATS_ID) && !on(&back, DOCK_ID));
    }
}
